<script lang="ts">
  import { marked } from 'marked';
  import { router } from '../../platform/router/router';
  import SourcePage from '../../ui/layout/SourcePage.svelte';
  interface NoteEntry { id:string; title:string; filename:string; date:string; description:string; }
  let notes=$state<NoteEntry[]>([]), selected=$state<NoteEntry>(), html=$state(''), loading=$state(true), articleLoading=$state(false), error=$state('');
  let loadedManifest=false, loadedArticle='';
  const noteId=$derived((router.route.params as Record<string, string | undefined>).noteId||'');
  function formatDate(value:string){const [y,m,d]=value.split('-').map(Number);return y&&m&&d?new Intl.DateTimeFormat('en-US',{year:'numeric',month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(Date.UTC(y,m-1,d))):value}
  function prepare(value:string){return value.replace(/\]\(attachments\//g,'](/notes/attachments/').replace(/^:::details\s+(.+)$/gm,'<details class="np-md-details"><summary>$1</summary><div class="np-md-details-body">').replace(/^:::\s*$/gm,'</div></details>')}
  async function loadManifest(){if(loadedManifest)return;loadedManifest=true;loading=true;try{const response=await fetch('/notes/manifest.json');if(!response.ok)throw new Error(`Failed to load manifest: ${response.status}`);notes=(await response.json() as NoteEntry[]).sort((a,b)=>b.date.localeCompare(a.date))}catch(reason){error=reason instanceof Error?reason.message:'Research notes could not be loaded.'}finally{loading=false}}
  async function loadArticle(id:string){if(!id||loadedArticle===id)return;const entry=notes.find(note=>note.id===id);selected=entry;html='';if(!entry)return;loadedArticle=id;articleLoading=true;try{const response=await fetch(`/notes/${entry.filename}`);if(!response.ok)throw new Error(`Failed to load note: ${response.status}`);html=String(marked.parse(prepare(await response.text()),{gfm:true}))}catch(reason){error=reason instanceof Error?reason.message:'The note could not be loaded.'}finally{articleLoading=false}}
  $effect(()=>{void loadManifest()});
  $effect(()=>{if(!loading&&noteId)void loadArticle(noteId);else if(!noteId){selected=undefined;html='';loadedArticle=''}});
</script>

<svelte:head><title>{selected?`${selected.title} · Research Notes`:'Research Notes'} · uma.moe</title><meta name="description" content={selected?.description??'Research notes from Hakuraku.'}/></svelte:head>
<SourcePage routeId="research-notes" title="Research Notes" width="normal" source="hakuraku">
  {#if loading}<div class="np-loading">Loading notes…</div>
  {:else if error}<div class="np-error">Error: {error}</div>
  {:else if selected}<div class="np-content-wrapper"><a href="/research-notes" class="np-back-btn">← Back to Notes</a>{#if articleLoading}<div class="np-md-loading">Loading…</div>{:else}<time class="np-note-date" datetime={selected.date}>Published {formatDate(selected.date)}</time><article class="np-md-container">{@html html}</article>{/if}</div>
  {:else}<div class="np-container"><div class="np-header"><p>Some notes on stuff I come across while looking at this game.</p></div>{#if notes.length}<div class="np-grid">{#each notes as note}<a class="np-card" href={`/research-notes/${note.id}`}><time datetime={note.date}>Published {formatDate(note.date)}</time><h3>{note.title}</h3><p>{note.description}</p></a>{/each}</div>{:else}<p class="np-empty">No notes yet.</p>{/if}</div>{/if}
</SourcePage>

<style>
  .np-container{padding:20px;max-width:900px;margin:0 auto}.np-header{padding-bottom:16px;margin-bottom:28px;border-bottom:1px solid var(--haku-border)}.np-header p{margin:6px 0 0;color:var(--haku-text-secondary);font-size:.9rem}.np-empty{color:var(--haku-text-muted)}.np-grid{display:grid;gap:16px}.np-card{display:block;padding:20px;border:1px solid var(--haku-border);border-radius:var(--haku-radius);background:var(--haku-bg-2);box-shadow:var(--haku-shadow);color:inherit;text-decoration:none;transition:border-color .18s ease,box-shadow .18s ease}.np-card:hover{border-color:#65d283;box-shadow:0 4px 20px rgb(101 210 131/.2)}.np-card time{display:inline-flex;width:fit-content;margin-bottom:12px;padding:4px 9px;border:1px solid rgb(168 230 184/.4);border-radius:999px;background:rgb(101 210 131/.12);color:#a8e6b8;font-size:.78rem;font-weight:700}.np-card h3{margin:0 0 8px;color:var(--haku-text-primary);font-size:1.1rem}.np-card p{margin:0;color:var(--haku-text-secondary);font-size:.9rem}.np-loading,.np-error{padding:40px 20px}.np-loading{color:var(--haku-text-secondary)}.np-error{color:#f87171}.np-content-wrapper{padding:20px;max-width:800px;margin:0 auto}.np-back-btn{display:inline-block;margin-bottom:24px;padding:6px 14px;border:1px solid var(--haku-border);border-radius:var(--haku-radius);color:var(--haku-text-secondary);font-size:.9rem;text-decoration:none}.np-md-loading{color:var(--haku-text-muted)}.np-note-date{display:block;margin:-8px 0 12px;color:#a8e6b8;font-size:.88rem;font-weight:700}.np-md-container{min-width:0;padding:clamp(16px,5vw,28px) clamp(16px,5vw,32px);overflow-wrap:break-word;border:1px solid var(--haku-border);border-radius:var(--haku-radius);background:var(--haku-bg-2);box-shadow:var(--haku-shadow);line-height:1.7}.np-md-container :global(h1){padding-bottom:10px;margin-bottom:20px;border-bottom:1px solid var(--haku-border);color:var(--haku-text-primary);overflow-wrap:break-word}.np-md-container :global(h2){margin-top:32px;color:var(--haku-text-primary)}.np-md-container :global(h3),.np-md-container :global(strong){color:var(--haku-text-primary)}.np-md-container :global(p),.np-md-container :global(li){color:var(--haku-text-secondary)}.np-md-container :global(a){color:var(--haku-accent)}.np-md-container :global(img){width:calc(100% + 2 * clamp(16px,5vw,32px));max-width:none;height:auto;margin:16px calc(-1 * clamp(16px,5vw,32px));border:1px solid var(--haku-border);border-radius:6px}.np-md-container :global(table){width:100%;border-collapse:collapse}.np-md-container :global(th),.np-md-container :global(td){padding:6px 12px;border:1px solid var(--haku-border);text-align:center}.np-md-container :global(th){background:var(--haku-bg-3);color:var(--haku-text-primary)}.np-md-container :global(td){color:var(--haku-text-secondary)}.np-md-container :global(.np-md-details){margin:14px 0 18px;border:1px solid var(--haku-border);border-radius:6px;background:rgb(255 255 255/.03)}.np-md-container :global(summary){padding:9px 12px;color:var(--haku-text-primary);font-weight:600;cursor:pointer}.np-md-container :global(.np-md-details-body){padding:0 12px 12px}.np-md-container :global(code){padding:1px 5px;border-radius:3px;background:rgb(255 255 255/.08);color:#a5d6a7;font-family:var(--font-mono)}.np-md-container :global(pre){overflow-x:auto;background:#1e1e1e;padding:10px 14px}@media(max-width:600px){.np-container,.np-content-wrapper{padding:8px 4px}.np-card{padding:14px 10px}.np-md-container{padding:14px 6px}.np-md-container :global(img){width:calc(100% + 12px);margin-inline:-6px}}
</style>
